 const GL=Array.isArray(q.l2.gloss)?q.l2.gloss:[];if(GL.length){const RK={'3':0,'4':1,'2':2,'1':3};const tr=GL.filter(g=>g.status==='GLOSS TRIMMED').sort((a,b)=>(RK[String(a.round).slice(-1)]??4)-(RK[String(b.round).slice(-1)]??4));const pt=GL.filter(g=>g.status==='PART').length;L.push('GLOSS CHECK -- computed by the system, not by a model, against the record\'s lexicon, the entries both debaters were served on their [L2] sheet (no gloss is given to you; md_notes_rulings 382, 383): '+GL.length+' lexicon meanings quoted; '+(GL.length-tr.length-pt)+' WHOLE; '+pt+' one sense or one rendering quoted alone (not listed); '+tr.length+' GLOSS TRIMMED, a quotation that gives the entry as a list and leaves out senses of it. Trimmed lines are listed link rounds first, then closes, then rounds 2 and 1; each prints only the senses the quotation left out. A meaning shown by cutting a lexicon line fails (Commitment 7): weigh what was left out against the meaning the side drew from its quotation.');for(const g of tr.slice(0,60))L.push(g.side+' ['+g.round+'] '+g.num+(g.word?' ('+g.word+')':'')+': GLOSS TRIMMED -- quoted "'+g.quote+'" -- left out: "'+g.missing+'"');if(tr.length>60)L.push((tr.length-60)+' more trimmed quotations are not listed.');} /* judge_fix10 G */
